using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using TCAdmin.SDK.Database.Managers;
using TCAdmin.Web.Shared.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Arma 3 (Linux) Workshop mods: each item lives in <root>/@<fileId>, its signing keys are copied to
// <root>/keys, and "@<fileId>" is kept in the Mods variable that feeds -mod=.
// The Linux server only finds mod files whose names are all lowercase, so the install lowercases the tree.
string root = ThisService.RootDirectory;
string fileId = Convert.ToString(Dynamic.FileId);
string modName = "@" + fileId;
string modFolder = Path.Combine(root, modName);
string rootKeys = Path.Combine(root, "keys");
const string KeyListFile = "tca-keys.txt";

void Log(string s) => ScriptConsole.WriteLine((object)s);

List<string> SplitList(string value) =>
    (value ?? string.Empty).Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList();

// Keys listed by every installed mod except this one, so an uninstall never deletes a key another mod still needs.
HashSet<string> KeysUsedByOtherMods()
{
    var used = new HashSet<string>(StringComparer.Ordinal);
    foreach (var dir in Directory.GetDirectories(root, "@*"))
    {
        if (string.Equals(Path.GetFileName(dir), modName, StringComparison.Ordinal)) continue;
        string list = Path.Combine(dir, KeyListFile);
        if (File.Exists(list)) used.UnionWith(File.ReadAllLines(list).Select(l => l.Trim()).Where(l => l.Length > 0));
    }
    return used;
}

async Task UpdateModsVariable(Func<List<string>, List<string>> change)
{
    var service = await ServiceManager.GetDbSet().FindAsync(ThisService.ServiceId);
    if (service == null) throw new InvalidOperationException("Service " + ThisService.ServiceId + " not found.");
    var current = service.Variables ?? new TCAdminVars();
    var mods = change(SplitList(current.Parse<string>("Mods", string.Empty)));
    string newMods = string.Join(";", mods);

    var updated = new TCAdminVars();
    foreach (var pair in current) updated[pair.Key] = pair.Value;
    updated["Mods"] = newMods;
    service.Variables = updated;
    ServiceManager.TCAdminDbContext.Entry(service).State = EntityState.Modified;
    await ServiceManager.TCAdminDbContext.SaveChangesAsync(ThisCancellationToken);

    // Mods is a command-line variable: re-derive the stored start command so the next start uses it.
    var refresh = await ServiceManager.RefreshActiveCommandLine(null, service, new CommandlineRefreshOptions { SaveChanges = true });
    if (refresh.Error != null) Log("Warning: the command line was not refreshed: " + refresh.Error);
    Log("Mods=" + newMods);
}

string installPath = Convert.ToString(Dynamic.InstallPath);
if (string.IsNullOrEmpty(installPath) || !Directory.Exists(installPath))
    throw new DirectoryNotFoundException("Workshop item " + fileId + " was not found at " + installPath + ".");

// Replace any previous copy (a Workshop update re-runs this script).
if (Directory.Exists(modFolder)) Directory.Delete(modFolder, true);
Directory.Move(installPath, modFolder);

// Lowercase every file and folder name, deepest first so parent paths stay valid while renaming.
int renamed = 0;
var entries = Directory.GetFileSystemEntries(modFolder, "*", SearchOption.AllDirectories)
    .OrderByDescending(p => p.Count(c => c == Path.DirectorySeparatorChar));
foreach (var path in entries)
{
    string name = Path.GetFileName(path);
    string lower = name.ToLowerInvariant();
    if (name == lower) continue;
    string target = Path.Combine(Path.GetDirectoryName(path), lower);
    if (File.Exists(target) || Directory.Exists(target))
    {
        Log("Warning: not renaming " + path + " because " + target + " already exists.");
        continue;
    }
    if (Directory.Exists(path)) Directory.Move(path, target); else File.Move(path, target);
    renamed++;
}
Log("Installed " + modName + " (" + renamed + " names lowercased).");

// Copy the mod's signing keys (keys/ or key/) to the server's keys folder and remember them for the uninstall.
Directory.CreateDirectory(rootKeys);
var keyNames = new List<string>();
foreach (var keyDir in Directory.GetDirectories(modFolder).Where(d => Path.GetFileName(d) is "keys" or "key"))
{
    foreach (var key in Directory.GetFiles(keyDir, "*.bikey", SearchOption.AllDirectories))
    {
        string keyName = Path.GetFileName(key);
        File.Copy(key, Path.Combine(rootKeys, keyName), true);
        if (!keyNames.Contains(keyName)) keyNames.Add(keyName);
    }
}
await File.WriteAllLinesAsync(Path.Combine(modFolder, KeyListFile), keyNames, ThisCancellationToken);
Log(keyNames.Count == 0 ? "The mod has no signing keys." : "Keys copied: " + string.Join(", ", keyNames));

await UpdateModsVariable(mods =>
{
    if (!mods.Contains(modName, StringComparer.Ordinal)) mods.Add(modName);
    return mods;
});

